const THREE={MathUtils:{smoothstep:(x,a,b)=>{const t=clamp((x-a)/(b-a),0,1);return t*t*(3-2*t);}}};
const state={power:true,heat:.6,amount:.55,room:.2,warmth:1,bulb:1,time:0};
const positions=Array.from({length:12},()=>({set(x,y,z,r){this.x=x;this.y=y;this.z=z;this.r=r;}}));
const shapes=Array.from({length:12},()=>({set(x,y,z,w){Object.assign(this,{x,y,z,w});}}));
let seed=123;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
const {simulate,parcels}=new Function('THREE','state','blobPositions','blobShapes','random','clamp','BLOB_COUNT',code+';return {simulate,parcels}')(THREE,state,positions,shapes,random,clamp,12);
let minY=4,maxY=0,rises=0,falls=0,nans=0;const samples=[];
