 simulate(1/90);
 if(step>9000){for(const b of parcels){minY=Math.min(minY,b.y);maxY=Math.max(maxY,b.y);if(b.vy>.02)rises++;if(b.vy<-.02)falls++;if("'!Number.isFinite(b.y+b.x+b.z+b.temp+b.vy))nans++;}}
